    @Test
    void exemplo5() throws Exception {
        confere(enviar(CAMISETA_TENIS, """
                "modalidadeEntrega":"EXPRESSA","formaPagamento":"PIX","nivelClube":"OURO","regiao":"SUDESTE\""""),
